export async function createSaasSocialChannelIdea(ctx: SocialContext, input: Omit<SaasSocialChannelIdea, "id" | "tenantId" | "saasId" | "createdAt" | "updatedAt"> & { id?: string }): Promise<SaasSocialChannelIdea> { const now = nowIso(); const saasId = requireSaasId(ctx); const id = input.id?.trim() ?? generateUuid(); await runStatement(ctx.socialDb, `INSERT INTO saas_social_channel_ideas (id, tenant_id, saas_id, channel_id, title, angle, summary, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET title = excluded.title, angle = excluded.angle, summary = excluded.summary, status = excluded.status, updated_at = excluded.updated_at`, id, ctx.tenantId, saasId, input.channelId, input.title, input.angle ?? null, input.summary ?? null, input.status ?? "idea", now, now); const row = await queryFirst<SocialChannelIdeaRow>(ctx.socialDb, `SELECT id, tenant_id, saas_id, channel_id, title, angle, summary, status, created_at, updated_at FROM saas_social_channel_ideas WHERE tenant_id = ? AND saas_id = ? AND id = ? LIMIT 1`, ctx.tenantId, saasId, id); if (!row) throw new SocialContextError("Unable to persist social channel idea."); return mapChannelIdeaRow(row); }
