export async function refreshSocialPostLiveAnalytics(ctx: SocialContext, postId: string, _input?: { force?: boolean }): Promise<{ ok: boolean; code: string; message: string; post: SaasSocialPost | null }> { const post = await getSaasSocialPostById(ctx, postId); if (!post) return { ok: false, code: "POST_NOT_FOUND", message: "Post not found", post: null }; const metrics = await listSaasSocialMetricsForPost(ctx, postId); const latest = metrics[0] ?? null; if (!latest) { const analytics = { source: "unavailable", impressions: 0, likes: 0, comments: 0, shares: 0, clicks: 0, engagement: 0, lastFetchedAt: nowIso(), lastRefreshStatus: "error" as const, lastRefreshErrorMessage: "No metrics stored for this post in SOCIAL_DB.", lastRefreshErrorCode: "SOCIAL_METRICS_MISSING" }; await upsertSaasSocialPost(ctx, { id: post.id, saasId: post.saasId, channelId: post.channelId ?? null, campaignId: post.campaignId, provider: post.provider, contentType: post.contentType, title: post.title, body: post.body, imageHint: post.imageHint, status: post.status, scheduledAt: post.scheduledAt, postedAt: post.postedAt, externalPostId: post.externalPostId, metadata: mergeMetadata(post.metadata, { analytics }) }); return { ok: false, code: "SOCIAL_METRICS_MISSING", message: "No metrics stored for this post in SOCIAL_DB.", post: await getSaasSocialPostById(ctx, post.id) }; } const analytics = { source: "social_db", impressions: latest.impressions, likes: latest.likes, comments: latest.comments, shares: latest.shares, clicks: latest.clicks, engagement: latest.likes + latest.comments + latest.shares + latest.clicks, lastFetchedAt: latest.capturedAt, lastRefreshStatus: "success" as const, lastRefreshErrorMessage: null, lastRefreshErrorCode: null }; await upsertSaasSocialPost(ctx, { id: post.id, saasId: post.saasId, channelId: post.channelId ?? null, campaignId: post.campaignId, provider: post.provider, contentType: post.contentType, title: post.title, body: post.body, imageHint: post.imageHint, status: post.status, scheduledAt: post.scheduledAt, postedAt: post.postedAt, externalPostId: post.externalPostId, metadata: mergeMetadata(post.metadata, { analytics }) }); return { ok: true, code: "SOCIAL_ANALYTICS_SYNCED", message: "Analytics refreshed from SOCIAL_DB.", post: await getSaasSocialPostById(ctx, post.id) }; }
