export async function upsertSaasSocialAccount(ctx: SocialContext, input: Omit<SaasSocialAccount, "id" | "tenantId" | "createdAt" | "updatedAt"> & { id?: string }): Promise<SaasSocialAccount> { const saasId = input.saasId?.trim() ?? requireSaasId(ctx); const id = input.id?.trim() ?? generateUuid(); const now = nowIso(); if (input.isPrimary) await runStatement(ctx.socialDb, `UPDATE saas_social_accounts SET is_primary = 0, updated_at = ? WHERE tenant_id = ? AND saas_id = ?`, now, ctx.tenantId, saasId); await runStatement(ctx.socialDb, `INSERT INTO saas_social_accounts (id, tenant_id, saas_id, provider, handle, display_name, status, auth_meta, is_primary, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET provider = excluded.provider, handle = excluded.handle, display_name = excluded.display_name, status = excluded.status, auth_meta = excluded.auth_meta, is_primary = excluded.is_primary, updated_at = excluded.updated_at`, id, ctx.tenantId, saasId, input.provider, input.handle ?? null, input.displayName ?? null, input.status, serializeJson(input.authMeta), input.isPrimary ? 1 : 0, now, now); await ensureChannelForProvider({ ...ctx, saasId }, input.provider); const row = await queryFirst<SocialAccountRow>(ctx.socialDb, `SELECT id, tenant_id, saas_id, provider, handle, display_name, status, auth_meta, is_primary, created_at, updated_at FROM saas_social_accounts WHERE tenant_id = ? AND saas_id = ? AND id = ? LIMIT 1`, ctx.tenantId, saasId, id); if (!row) throw new SocialContextError("Unable to persist social account."); return mapAccountRow(row); }
