export async function listSaasSocialPosts(ctx: SocialContext, filters?: { campaignId?: string | null; status?: string | null; provider?: SaasSocialProvider | null }): Promise<SaasSocialPost[]> { const saasId = requireSaasId(ctx); const clauses = ["tenant_id = ?", "saas_id = ?"]; const params: unknown[] = [ctx.tenantId, saasId]; if (filters?.campaignId) { clauses.push("campaign_id = ?"); params.push(filters.campaignId); } if (filters?.status) { clauses.push("status = ?"); params.push(filters.status); } if (filters?.provider) { clauses.push("provider = ?"); params.push(filters.provider); } const rows = await queryRows<SocialPostRow>(ctx.socialDb, `SELECT id, tenant_id, saas_id, channel_id, campaign_id, provider, content_type, title, body, image_hint, status, scheduled_at, posted_at, external_post_id, metadata, created_at, updated_at FROM saas_social_posts WHERE ${clauses.join(" AND ")} ORDER BY datetime(created_at) DESC`, ...params); return rows.map(mapPostRow); }
