export async function updateSaasSocialPostStatus(ctx: SocialContext, input: { id: string; status: SaasSocialPost["status"]; postedAt?: string | null }): Promise<SaasSocialPost | null> { const post = await getSaasSocialPostById(ctx, input.id); if (!post) return null; const publication = typeof post.metadata?.publication === "object" && post.metadata.publication ? (post.metadata.publication as Record<string, unknown>) : {}; const metadata = mergeMetadata(post.metadata, { publication: { ...publication, state: input.status === "FAILED" ? "failed" : input.status === "PUBLISHED" || input.status === "POSTED" ? "published" : "queued", mode: input.status === "PUBLISHED" || input.status === "POSTED" ? "live" : publication.mode ?? null, lastAttemptAt: nowIso(), externalPostId: post.externalPostId } }); await upsertSaasSocialPost(ctx, { id: post.id, saasId: post.saasId, channelId: post.channelId ?? null, campaignId: post.campaignId, provider: post.provider, contentType: post.contentType, title: post.title, body: post.body, imageHint: post.imageHint, status: input.status, scheduledAt: post.scheduledAt, postedAt: input.status === "POSTED" || input.status === "PUBLISHED" ? input.postedAt ?? nowIso() : post.postedAt, externalPostId: post.externalPostId, metadata }); return getSaasSocialPostById(ctx, input.id); }
